query:
SELECT COUNT(*) AS non_innodb_tables FROM information_schema.TABLES 
WHERE TABLE_SCHEMA = DATABASE() AND ENGINE != 'InnoDB';

SELECT COUNT(*) AS orphan_count
FROM fire_alarm_inspection_results r
LEFT JOIN fire_alarm_checklist_templates t ON r.checklistItemId = t.id
WHERE t.id IS NULL;

SELECT COUNT(*) AS audit_log_exists FROM information_schema.TABLES 
WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('audit_log', 'migration_log');

